{"command":"$ErrorActionPreference='Stop'
$r='C:\Users\spay\Documents\Obsidian Vault\Screen Notes'
function Get-GitRaw([string]$argsLine) {
  $psi = [Diagnostics.ProcessStartInfo]::new()
  $psi.FileName = 'git'
  $psi.WorkingDirectory = $r
  foreach ($a in ($argsLine -split ' ')) { $psi.ArgumentList.Add($a) }
  $psi.RedirectStandardOutput = $true
  $psi.RedirectStandardError = $true
  $psi.UseShellExecute = $false
  $p = [Diagnostics.Process]::Start($psi)
  $ms = [IO.MemoryStream]::new()
  $p.StandardOutput.BaseStream.CopyTo($ms)
  $p.WaitForExit()
  return $ms.ToArray()
}
foreach ($f in @('screenpipe-chat-2026-04-06T04-57-45.md','screenpipe-chat-2026-04-11T19-17-05.md')) {
  $bytes = Get-GitRaw "cat-file -p test1:$f"
  $c=0;$l=0
  for($i=0;$i -lt $bytes.Length;$i++){ if($bytes[$i] -eq 10){ if($i -gt 0 -and $bytes[$i-1] -eq 13){$c++}else{$l++} } }
  "   BLOB $f -> bytes=$($bytes.Length)  CRLF=$c  bareLF=$l"
}","description":"Побайтовая проверка окончаний строк в blob"}

